#include "tigersheets/session.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
void capture(){WorkbookSession session;const auto captured=session.captureSnapshot();require(session.apply(0,Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",3},{"input","42"}}})),"capture edit setup");require(captured->at("revision")==0&&captured->at("sheets")[0].at("cells").empty(),"immutable captured snapshots survive later workbook edits");require(session.snapshotView().at("revision")==1&&session.cellAt("sheet-1",2,3)&&session.cellAt("sheet-1",2,3)->at("input")=="42"&&!session.cellAt("sheet-1",1,1),"zero-copy view and indexed cell reads expose current canonical state");}
void deltaHistory(){Json book={{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",Json::array()}}})}};for(int row=1;row<=20000;++row)book["sheets"][0]["cells"].push_back({{"row",row},{"col",1},{"input",std::to_string(row)}});WorkbookSession session(std::move(book));
 require(session.apply(0,Json::array({{{"type","set_cell"},{"sheet","s"},{"row",10000},{"col",1},{"input","changed"}},{{"type","set_style"},{"sheet","s"},{"row",10000},{"col",1},{"style",{{"bold",true}}}}})),"large-source repeated-coordinate transaction");require(session.historyBytes()<8192,"one edited cell must retain a small undo delta rather than a complete source workbook");
 require(session.lastChange().at("structure")==false&&session.lastChange().at("sheets").size()==1&&session.lastChange().at("sheets")[0].at("row1")==10000&&session.lastChange().at("sheets")[0].at("row2")==10000,"cell transactions expose a bounded refresh footprint");
 require(session.undo()&&session.cellAt("s",10000,1)->at("input")=="10000"&&!session.cellAt("s",10000,1)->contains("style"),"delta undo restores original content and style");require(session.redo()&&session.cellAt("s",10000,1)->at("input")=="changed"&&session.cellAt("s",10000,1)->at("style").at("bold")==true,"delta redo restores the complete cell edit");
 const auto before=session.snapshot();const auto bytes=session.historyBytes();require(!session.apply(before.at("revision"),Json::array({{{"type","set_cell"},{"sheet","s"},{"row",1},{"col",1},{"input","leak"}},{{"type","set_style"},{"sheet","s"},{"row",2},{"col",1},{"style",{{"fontSize",0}}}}})),"invalid later style refuses the staged cell batch");require(session.snapshot()==before&&session.historyBytes()==bytes,"failed staged edits preserve source and history");}
void rangeHistory(){Json book={{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",Json::array()}}})}};Json replacement=Json::array();for(int row=1;row<=5000;++row){const Json cell={{"row",row},{"col",1},{"input",std::string(128,'x')+std::to_string(row)}};book["sheets"][0]["cells"].push_back(cell);replacement.push_back(cell);if(row<=20)book["sheets"][0]["cells"].push_back({{"row",row},{"col",2},{"input","generated"}});if(row==1)replacement.push_back({{"row",row},{"col",2},{"input","generated"}});}WorkbookSession session(std::move(book));require(session.apply(0,Json::array({{{"type","replace_sheet_cells"},{"sheet","s"},{"cells",replacement}}})),"shrinking interleaved output setup");require(session.historyBytes()<65536,"shrinking a report must not retain unchanged source cells through shifted array-index patches");require(session.undo()&&session.cellAt("s",20,2)&&session.cellAt("s",5000,1)->at("input")==std::string(128,'x')+"5000","range undo restores report cells and untouched source");require(session.redo()&&!session.cellAt("s",20,2)&&session.cellAt("s",5000,1),"range redo removes only the obsolete report footprint");}
void suspendedPivotChartRanges(){
 auto accepts=[](const Json& book){try{WorkbookSession session(book);return true;}catch(const std::exception&){return false;}};
 for(const auto [rows,columns]:{std::pair{10002,2},std::pair{10,200}}){Json source={{"sheet","s"},{"row1",1},{"col1",1},{"row2",2},{"col2",2}},output={{"sheet","r"},{"row1",1},{"col1",1},{"row2",rows},{"col2",columns}};Json range=output;range.erase("sheet");Json pivot={{"version",1},{"id","p"},{"name","Report"},{"source",source},{"output",output},{"cache",{{"fields",Json::array()},{"records",Json::array()}}},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"}}})}};Json chart={{"id","c"},{"pivotId","p"},{"type","column"},{"title","Report"},{"sheet","r"},{"range",range}};Json book={{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Data"},{"cells",Json::array()}},{{"id","r"},{"name","Report"},{"cells",Json::array()}}})},{"pivots",Json::array({pivot})},{"charts",Json::array({chart})}};
 require(accepts(book),"managed PivotChart ranges must retain complete tall or wide reports beyond ordinary chart rendering limits");auto ordinary=book;ordinary["charts"][0].erase("pivotId");require(!accepts(ordinary),"ordinary chart range limits remain bounded");for(const auto* field:{"identity","type","range","sheet","bounds"}){auto invalid=book;if(std::string(field)=="identity")invalid["charts"][0]["pivotId"]="missing";else if(std::string(field)=="type")invalid["charts"][0]["type"]="scatter";else if(std::string(field)=="range")invalid["charts"][0]["range"]["row2"]=rows-1;else if(std::string(field)=="sheet")invalid["charts"][0]["sheet"]="s";else invalid["pivots"][0]["source"]["row1"]=0;require(!accepts(invalid),"PivotChart range exemption must retain owned identity type source bounds and complete output binding");}}
}
int main(int argc,char**argv){try{const auto test=argc>1?std::string(argv[1]):"all";if(test=="chart_limits"||test=="all")suspendedPivotChartRanges();if(test=="capture"||test=="all")capture();if(test=="delta"||test=="all")deltaHistory();if(test=="range"||test=="all")rangeHistory();std::cout<<"session foundation passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
